// 4. Cache-proof tracking (10 Nov 2026). GoDaddy's cache can serve stored redirects
//    and strip cookies, so the customer's browser keeps the code (localStorage) and
//    fills an optional "Curator code" box at checkout; the code travels with the order form.
// ─────────────────────────────────────────────────────────────────────────────
add_action( 'rest_api_init', function () {
	// visit log, sent once per code per device per 30 days by the browser script below
	register_rest_route( 'rew/v1', '/visit', array(
		'methods'             => 'POST',
		'permission_callback' => '__return_true',
		'callback'            => function ( WP_REST_Request $r ) {
			$p    = $r->get_json_params();
			$code = re_track_clean_code( $p['code'] ?? '' );
			if ( $code !== '' ) {
				re_track_send( array( 'event' => 'visit', 'curator_code' => $code ), false );
			}
			return new WP_REST_Response( array( 'ok' => true ), 200 );
		},
	) );
	// admin: re-send an order to the Seller Notebook (e.g. after adding a curator code by hand)
	register_rest_route( 'rew/v1', '/resync/(?P<id>\d+)', array(
		'methods'             => 'POST',
		'permission_callback' => function () { return current_user_can( 'manage_woocommerce' ); },
		'callback'            => function ( WP_REST_Request $r ) {
			$order = wc_get_order( (int) $r['id'] );
			if ( ! $order ) {
				return new WP_REST_Response( array( 'error' => 'no order' ), 404 );
			}
			return new WP_REST_Response( array( 'note' => re_track_report_order( $order, $order->get_status() ) ), 200 );
		},
	) );
} );

function re_track_report_order( $order, $status ) {
	$code = $order->get_meta( '_re_curator' );
	if ( ! $code ) {
		return 'no curator code on order';
	}
	$lines = array();
	foreach ( $order->get_items() as $item ) {
		$lines[] = array( 'woo_product_id' => (int) $item->get_product_id(), 'name' => $item->get_name(), 'qty' => (int) $item->get_quantity() );
	}
	$res  = re_track_send( array(
		'event'         => 'order',
		'order_id'      => (string) $order->get_id(),
		'status'        => $status,
		'curator_code'  => $code,
		'customer_name' => trim( $order->get_billing_first_name() . ' ' . $order->get_billing_last_name() ),
		'order_total'   => (float) $order->get_total(),
		'lines'         => $lines,
	), true );
	$note = is_wp_error( $res ) ? 'Curator tracking: could not reach Seller Notebook (' . $res->get_error_message() . ')' : 'Curator tracking (' . $code . '): ' . wp_remote_retrieve_body( $res );
	$order->add_order_note( substr( $note, 0, 300 ) );
	return $note;
}

