// Optional, pre-filled "Curator code" box on the checkout page
add_filter( 'woocommerce_checkout_fields', function ( $fields ) {
	$code = re_track_current_code();
	if ( $code === '' ) {
		$code = re_track_clean_code( $_COOKIE['wp_re_aff'] ?? '' );
	}
	$fields['order']['re_curator_code'] = array(
		'type'              => 'text',
		'label'             => 'Curator code (optional)',
		'placeholder'       => 'If a Rareearth curator referred you, e.g. REC2541',
		'required'          => false,
		'class'             => array( 'form-row-wide' ),
		'default'           => $code,
		'priority'          => 5,
		'custom_attributes' => array( 'maxlength' => '12', 'autocomplete' => 'off' ),
	);
	return $fields;
} );

// The code in the checkout box wins (one code per order, so no double counting)
add_action( 'woocommerce_checkout_create_order', function ( $order ) {
	$typed = re_track_clean_code( wp_unslash( $_POST['re_curator_code'] ?? '' ) );
	if ( $typed === '' ) {
		$typed = re_track_clean_code( $_COOKIE['wp_re_aff'] ?? '' );
	}
	if ( $typed !== '' ) {
		$order->update_meta_data( '_re_curator', $typed );
	}
}, 20, 1 );
